volatile uint32_t HW_FLAG_ADDR;
const uint32_t COMPLETE_MASK = 0x8000;

void wait_sync() {
    // Volatile prevents compiler from caching HW_FLAG_ADDR
    for (;;) {
        if (HW_FLAG_ADDR & COMPLETE_MASK) {
            break; // Non-standard exit condition
        }
        // Optional: Yield/Wait instruction
    }
}
